-- Conferência
select (select count(*) from public.products) as products,
       (select count(*) from public.clients) as clients,
       (select count(*) from public.sales) as sales,
       (select count(*) from public.sale_items) as sale_items,
       (select count(*) from public.stock_movements) as stock_movements,
       (select count(*) from public.fixed_costs) as fixed_costs,
       (select count(*) from public.expenses) as expenses,
       (select count(*) from public.cash_sessions) as cash_sessions,
       (select count(*) from public.cash_movements) as cash_movements,
       (select count(*) from public.orders) as orders,
       (select count(*) from public.order_items) as order_items,
       (select count(*) from public.kits) as kits,
       (select count(*) from public.kit_itens) as kit_itens;
